_cuda_src = r'''
extern "C" __global__
void l2_norm_kernel(const half* __restrict__ A,
                    half* __restrict__ O,
                    int dim) {
    // one block per row (batch element)
    int row = blockIdx.x;
    // each thread accumulates a chunk of the row
    float sum = 0.0f;
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        half hv = A[row * dim + i];
        float fv = __half2float(hv);
        sum += fv * fv;
    }
    // reduction in shared memory
    extern __shared__ float s[];
    s[threadIdx.x] = sum;
    __syncthreads();
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            s[threadIdx.x] += s[threadIdx.x + offset];
        }
        __syncthreads();
    }
    float inv_norm = rsqrtf(s[0] + 1e-12f);  // 1 / sqrt(sum)

    // write normalized values
    for (int i = threadIdx.x; i < dim; i += blockDim.x) {
        half hv = A[row * dim + i];
        float fv = __half2float(hv);
        O[row * dim + i] = __float2half(fv * inv_norm);
    }
}
'''

_cpp_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

void l2_norm_launcher(at::Tensor A, at::Tensor O) {
    TORCH_CHECK(A.is_cuda() && O.is_cuda(), "Tensors must be CUDA");
    TORCH_CHECK(A.dtype() == torch::kHalf && O.dtype() == torch::kHalf,
                "Tensors must be float16");
    TORCH_CHECK(A.sizes().size() == 2, "Input must be 2‑D");
    TORCH_CHECK(A.sizes() == O.sizes(), "Input and output shapes must match");

    int batch = A.size(0);
    int dim   = A.size(1);

    const int threads = 256;
    dim3 grid(batch);
    dim3 block(threads);
    size_t shared_mem = threads * sizeof(float);

    // launch kernel
    l2_norm_kernel<<<grid, block, shared_mem>>>(
        reinterpret_cast<const half*>(A.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        dim
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("l2_norm", &l2_norm_launcher, "L2‑normalization kernel (CUDA)");
}
'''

# Compile the extension (the compilation happens once at import time)
_l2norm_mod = load_inline(
    name="l2norm_cuda_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["l2_norm"],
    verbose=False,
)

# ----------------------------------------------------------------------
# PyTorch wrapper that calls the compiled kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference L2‑normalization model.
    All tensors are expected to be float16 (fp16).
    """
    def __init__(self):
        super().__init__()
        # The compiled module is stored as a class attribute for reuse.
        self._mod = _l2norm_mod

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.float16:
            raise TypeError("ModelNew expects fp16 (torch.float16) input")
        if not x.is_cuda:
            raise RuntimeError("Input tensor must be on CUDA device")
        # Ensure contiguous layout for pointer arithmetic
        x_contig = x.contiguous()
        out = torch.empty_like(x_contig)
        # Launch the kernel
        self._mod.l2_norm(x_contig, out)
        return out
